import React, { useState } from 'react';
import { FaPlane, FaTimes } from 'react-icons/fa';
import { useTheme } from '../context/ThemeContext';

const FlightSearch = ({ isOpen, onClose, departure, destination, dates }) => {
  const { theme } = useTheme();
  const [isLoading, setIsLoading] = useState(true);

  // Format dates for Google Flights URL
  const formatDate = (date) => {
    return date.toISOString().split('T')[0];
  };

  // Construct Google Flights URL
  const getGoogleFlightsUrl = () => {
    if (!departure || !destination || !dates) return null;

    const startDate = formatDate(dates.startDate);
    const endDate = formatDate(dates.endDate);
    
    return `https://www.google.com/travel/flights/search?tfs=${departure.name}_${destination.name}_${startDate}_${endDate}`;
  };

  if (!isOpen) return null;

  return (
    <div 
      className="fixed inset-0 z-50 flex items-center justify-center"
      style={{ backgroundColor: 'rgba(0, 0, 0, 0.5)' }}
    >
      <div 
        className="relative w-11/12 h-5/6 rounded-lg shadow-xl"
        style={{ 
          backgroundColor: theme.background,
          border: `1px solid ${theme.border}`
        }}
      >
        {/* Header */}
        <div 
          className="flex items-center justify-between p-4 border-b"
          style={{ borderColor: theme.border }}
        >
          <div className="flex items-center space-x-3">
            <FaPlane style={{ color: theme.primary }} className="text-xl" />
            <h2 className="text-xl font-semibold" style={{ color: theme.text }}>
              Flight Search
            </h2>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-full hover:bg-opacity-10 transition-colors"
            style={{ 
              color: theme.text,
              backgroundColor: `${theme.text}10`
            }}
          >
            <FaTimes />
          </button>
        </div>

        {/* Flight Search Content */}
        <div className="h-[calc(100%-4rem)]">
          {isLoading && (
            <div 
              className="absolute inset-0 flex items-center justify-center"
              style={{ backgroundColor: theme.background }}
            >
              <div className="text-lg" style={{ color: theme.text }}>
                Loading flight search...
              </div>
            </div>
          )}
          <iframe
            src={getGoogleFlightsUrl()}
            className="w-full h-full"
            onLoad={() => setIsLoading(false)}
            title="Flight Search"
            sandbox="allow-same-origin allow-scripts allow-popups allow-forms"
          />
        </div>
      </div>
    </div>
  );
};

export default FlightSearch;
